{
  "local_listener": "Get-NetTCPConnection -State Listen -LocalPort 18009; Get-CimInstance Win32_Process | Where-Object { $_.ProcessId -in (Get-NetTCPConnection -State Listen -LocalPort 18009).OwningProcess } | Select-Object ProcessId,Name,CommandLine",
  "dotenv": "Read .env keys in memory; write only model/mode, sanitized scheme+host+path, key-presence and env-override-presence; never values for credentials",
  "models_get": "GET http://127.0.0.1:18009/v1/models (read-only; no auth header)",
  "remote_readonly": "hostname; ps -eo pid,etimes,comm,args | grep '[k]ev.serve'; nvidia-smi --query-gpu=index,uuid,name,memory.total,memory.used --format=csv,noheader -i 1; nvidia-smi --query-compute-apps=gpu_uuid,pid,process_name,used_memory --format=csv,noheader -i 1"
}
